INSERT INTO templates (name, builtin, sort_order, html) VALUES
('Klar', 1, 0, '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;padding:0;background:#ffffff"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#ffffff"><tr><td align="center" style="padding:48px 20px"><table role="presentation" width="560" cellpadding="0" cellspacing="0" style="width:100%;max-width:560px;"><tr><td style="padding:0 8px 28px;border-bottom:1px solid #ececf0;font-family:-apple-system,BlinkMacSystemFont,Helvetica,Arial,sans-serif;font-size:12px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:#8a8a90">{{name}}</td></tr><tr><td style="padding:32px 8px;font-family:-apple-system,BlinkMacSystemFont,Helvetica,Arial,sans-serif;font-size:16px;line-height:1.7;color:#1d1d1f">{{inhalt}}</td></tr><tr><td style="padding:20px 8px 0;border-top:1px solid #ececf0;font-family:-apple-system,BlinkMacSystemFont,Helvetica,Arial,sans-serif;font-size:12px;color:#8a8a90"><a href="mailto:{{email}}" style="color:#8a8a90;text-decoration:none">{{email}}</a></td></tr></table></td></tr></table></body></html>'),
('Papier', 1, 1, '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;padding:0;background:#f3efe8"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f3efe8"><tr><td align="center" style="padding:40px 12px"><table role="presentation" width="580" cellpadding="0" cellspacing="0" style="width:100%;max-width:580px;background:#fffdf8;border-radius:4px;border:1px solid #e7e0d3"><tr><td style="height:6px;background:#2b2620;font-size:0;line-height:0">&nbsp;</td></tr><tr><td style="padding:44px 52px 12px;font-family:Georgia,Times,serif;font-size:13px;font-style:italic;color:#8b7f6e">{{name}}</td></tr><tr><td style="padding:8px 52px 44px;font-family:Georgia,Times,serif;font-size:17px;line-height:1.75;color:#2b2620">{{inhalt}}</td></tr></table></td></tr></table></body></html>'),
('Notiz', 1, 2, '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;padding:0;background:#f4f4f6"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f4f6"><tr><td align="center" style="padding:40px 12px"><table role="presentation" width="540" cellpadding="0" cellspacing="0" style="width:100%;max-width:540px;background:#fff6c9;border-radius:6px"><tr><td style="padding:30px 36px 6px"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="width:10px;height:10px;border-radius:5px;background:#f2b705;font-size:0">&nbsp;</td><td style="padding-left:10px;font-family:-apple-system,BlinkMacSystemFont,Helvetica,Arial,sans-serif;font-size:12px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:#8a6d00">Kurz notiert</td></tr></table></td></tr><tr><td style="padding:10px 36px 0;font-family:Georgia,Times,serif;font-size:24px;line-height:1.3;color:#3d3200">{{betreff}}</td></tr><tr><td style="padding:14px 36px 34px;font-family:-apple-system,BlinkMacSystemFont,Helvetica,Arial,sans-serif;font-size:15px;line-height:1.65;color:#3d3a2a">{{inhalt}}</td></tr></table></td></tr></table></body></html>'),
('Geschäftsbrief', 1, 3, '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;padding:0;background:#eef1f5"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#eef1f5"><tr><td align="center" style="padding:40px 12px"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="width:100%;max-width:600px;background:#ffffff;border-radius:10px;overflow:hidden"><tr><td style="padding:28px 44px;border-bottom:1px solid #e6eaf0"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td style="font-family:-apple-system,BlinkMacSystemFont,Helvetica,Arial,sans-serif;font-size:18px;font-weight:700;letter-spacing:-.01em;color:#1f3a5f">{{name}}</td><td align="right" style="font-family:-apple-system,BlinkMacSystemFont,Helvetica,Arial,sans-serif;font-size:12px;color:#7a8699"><a href="mailto:{{email}}" style="color:#7a8699;text-decoration:none">{{email}}</a></td></tr></table></td></tr><tr><td style="padding:36px 44px 8px;font-family:-apple-system,BlinkMacSystemFont,Helvetica,Arial,sans-serif;font-size:13px;font-weight:600;color:#1f3a5f">Betreff: {{betreff}}</td></tr><tr><td style="padding:12px 44px 40px;font-family:-apple-system,BlinkMacSystemFont,Helvetica,Arial,sans-serif;font-size:15px;line-height:1.7;color:#25303f">{{inhalt}}</td></tr><tr><td style="padding:20px 44px;background:#1f3a5f;font-family:-apple-system,BlinkMacSystemFont,Helvetica,Arial,sans-serif;font-size:12px;color:#c9d6e8">{{name}} &nbsp;·&nbsp; <a href="mailto:{{email}}" style="color:#ffffff;text-decoration:none">{{email}}</a></td></tr></table></td></tr></table></body></html>'),
('Angebot', 1, 4, '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;padding:0;background:#f1f3f6"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f1f3f6"><tr><td align="center" style="padding:40px 12px"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="width:100%;max-width:600px;background:#ffffff;border-radius:16px;overflow:hidden"><tr><td style="padding:44px 44px 40px;background:#0f172a"><div style="font-family:-apple-system,BlinkMacSystemFont,Helvetica,Arial,sans-serif;font-size:12px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:#7dd3fc">{{name}}</div><div style="margin-top:14px;font-family:-apple-system,BlinkMacSystemFont,Helvetica,Arial,sans-serif;font-size:30px;line-height:1.2;font-weight:800;letter-spacing:-.02em;color:#ffffff">{{betreff}}</div><div style="margin-top:20px;width:48px;height:4px;border-radius:2px;background:#38bdf8;font-size:0;line-height:0">&nbsp;</div></td></tr><tr><td style="padding:40px 44px 16px;font-family:-apple-system,BlinkMacSystemFont,Helvetica,Arial,sans-serif;font-size:15px;line-height:1.7;color:#1e293b">{{inhalt}}</td></tr><tr><td style="padding:8px 44px 40px"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="border-radius:10px;background:#0f172a"><a href="mailto:{{email}}" style="display:inline-block;padding:13px 22px;font-family:-apple-system,BlinkMacSystemFont,Helvetica,Arial,sans-serif;font-size:14px;font-weight:700;color:#ffffff;text-decoration:none">Antworten &rarr;</a></td></tr></table></td></tr><tr><td style="padding:22px 44px;background:#f8fafc;border-top:1px solid #e2e8f0;font-family:-apple-system,BlinkMacSystemFont,Helvetica,Arial,sans-serif;font-size:12px;color:#64748b">{{name}} · {{email}}</td></tr></table></td></tr></table></body></html>'),
('Executive', 1, 5, '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;padding:0;background:#151517"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#151517"><tr><td align="center" style="padding:48px 12px"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="width:100%;max-width:600px;background:#ffffff"><tr><td style="height:3px;background:#b08d57;font-size:0;line-height:0">&nbsp;</td></tr><tr><td align="center" style="padding:44px 48px 8px;font-family:Georgia,Times,serif;font-size:13px;letter-spacing:.22em;text-transform:uppercase;color:#b08d57">{{name}}</td></tr><tr><td align="center" style="padding:8px 48px 0;font-family:Georgia,Times,serif;font-size:28px;line-height:1.25;color:#151517">{{betreff}}</td></tr><tr><td align="center" style="padding:22px 0 6px"><div style="width:36px;height:1px;background:#b08d57;font-size:0;line-height:0">&nbsp;</div></td></tr><tr><td style="padding:24px 56px 48px;font-family:-apple-system,BlinkMacSystemFont,Helvetica,Arial,sans-serif;font-size:15px;line-height:1.75;color:#2a2a2e">{{inhalt}}</td></tr><tr><td align="center" style="padding:22px 48px;background:#151517;font-family:Georgia,Times,serif;font-size:12px;letter-spacing:.08em;color:#b08d57">{{email}}</td></tr></table></td></tr></table></body></html>'),
('Einladung', 1, 6, '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;padding:0;background:#fff1ea"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#fff1ea"><tr><td align="center" style="padding:40px 12px"><table role="presentation" width="560" cellpadding="0" cellspacing="0" style="width:100%;max-width:560px;background:#ffffff;border-radius:22px;overflow:hidden"><tr><td align="center" style="padding:52px 40px 44px;background:#ff7a59"><div style="font-family:Georgia,Times,serif;font-size:18px;letter-spacing:.5em;color:#ffe3d8">&#10022; &#10022; &#10022;</div><div style="margin-top:14px;font-family:-apple-system,BlinkMacSystemFont,Helvetica,Arial,sans-serif;font-size:12px;font-weight:700;letter-spacing:.24em;text-transform:uppercase;color:#ffffff">Einladung</div><div style="margin-top:12px;font-family:Georgia,Times,serif;font-size:36px;line-height:1.15;color:#ffffff">{{betreff}}</div></td></tr><tr><td align="center" style="padding:40px 48px 12px;font-family:-apple-system,BlinkMacSystemFont,Helvetica,Arial,sans-serif;font-size:16px;line-height:1.75;color:#3b2a24">{{inhalt}}</td></tr><tr><td align="center" style="padding:12px 48px 48px;font-family:Georgia,Times,serif;font-size:18px;font-style:italic;color:#ff7a59">Herzlich, {{name}}</td></tr></table></td></tr></table></body></html>'),
('Feier', 1, 7, '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;padding:0;background:#f6f2ff"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f6f2ff"><tr><td align="center" style="padding:40px 12px"><table role="presentation" width="560" cellpadding="0" cellspacing="0" style="width:100%;max-width:560px;background:#ffffff;border-radius:22px"><tr><td align="center" style="padding:40px 24px 0"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="padding:0 5px"><div style="width:12px;height:12px;border-radius:6px;background:#ff5d8f;font-size:0;line-height:0">&nbsp;</div></td><td style="padding:0 5px"><div style="width:8px;height:8px;border-radius:4px;background:#ffc145;font-size:0;line-height:0">&nbsp;</div></td><td style="padding:0 5px"><div style="width:14px;height:14px;border-radius:7px;background:#4cc9f0;font-size:0;line-height:0">&nbsp;</div></td><td style="padding:0 5px"><div style="width:9px;height:9px;border-radius:4px;background:#7b61ff;font-size:0;line-height:0">&nbsp;</div></td><td style="padding:0 5px"><div style="width:12px;height:12px;border-radius:6px;background:#3ddc97;font-size:0;line-height:0">&nbsp;</div></td><td style="padding:0 5px"><div style="width:8px;height:8px;border-radius:4px;background:#ff8c42;font-size:0;line-height:0">&nbsp;</div></td><td style="padding:0 5px"><div style="width:10px;height:10px;border-radius:5px;background:#ff5d8f;font-size:0;line-height:0">&nbsp;</div></td><td style="padding:0 5px"><div style="width:8px;height:8px;border-radius:4px;background:#4cc9f0;font-size:0;line-height:0">&nbsp;</div></td></tr></table></td></tr><tr><td align="center" style="padding:26px 44px 0;font-family:-apple-system,BlinkMacSystemFont,Helvetica,Arial,sans-serif;font-size:38px;line-height:1.1;font-weight:800;letter-spacing:-.02em;color:#7b61ff">{{betreff}}</td></tr><tr><td align="center" style="padding:24px 48px 16px;font-family:-apple-system,BlinkMacSystemFont,Helvetica,Arial,sans-serif;font-size:16px;line-height:1.7;color:#2e2a3d">{{inhalt}}</td></tr><tr><td align="center" style="padding:8px 24px 40px"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="padding:0 5px"><div style="width:12px;height:12px;border-radius:6px;background:#ff5d8f;font-size:0;line-height:0">&nbsp;</div></td><td style="padding:0 5px"><div style="width:8px;height:8px;border-radius:4px;background:#ffc145;font-size:0;line-height:0">&nbsp;</div></td><td style="padding:0 5px"><div style="width:14px;height:14px;border-radius:7px;background:#4cc9f0;font-size:0;line-height:0">&nbsp;</div></td><td style="padding:0 5px"><div style="width:9px;height:9px;border-radius:4px;background:#7b61ff;font-size:0;line-height:0">&nbsp;</div></td><td style="padding:0 5px"><div style="width:12px;height:12px;border-radius:6px;background:#3ddc97;font-size:0;line-height:0">&nbsp;</div></td><td style="padding:0 5px"><div style="width:8px;height:8px;border-radius:4px;background:#ff8c42;font-size:0;line-height:0">&nbsp;</div></td><td style="padding:0 5px"><div style="width:10px;height:10px;border-radius:5px;background:#ff5d8f;font-size:0;line-height:0">&nbsp;</div></td><td style="padding:0 5px"><div style="width:8px;height:8px;border-radius:4px;background:#4cc9f0;font-size:0;line-height:0">&nbsp;</div></td></tr></table><div style="margin-top:18px;font-family:-apple-system,BlinkMacSystemFont,Helvetica,Arial,sans-serif;font-size:13px;font-weight:600;color:#8d86a3">{{name}}</div></td></tr></table></td></tr></table></body></html>'),
('Sommer', 1, 8, '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;padding:0;background:#e9f7f4"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#e9f7f4"><tr><td align="center" style="padding:40px 12px"><table role="presentation" width="580" cellpadding="0" cellspacing="0" style="width:100%;max-width:580px;background:#ffffff;border-radius:18px;overflow:hidden"><tr><td style="padding:0;font-size:0;line-height:0"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td style="height:10px;background:#0f766e">&nbsp;</td><td style="height:10px;background:#14b8a6">&nbsp;</td><td style="height:10px;background:#fbbf24">&nbsp;</td><td style="height:10px;background:#fb7185">&nbsp;</td></tr></table></td></tr><tr><td style="padding:40px 44px 0;font-family:-apple-system,BlinkMacSystemFont,Helvetica,Arial,sans-serif;font-size:13px;font-weight:700;color:#0f766e">Hallo aus dem Postfach von {{name}} &#9728;</td></tr><tr><td style="padding:10px 44px 0;font-family:-apple-system,BlinkMacSystemFont,Helvetica,Arial,sans-serif;font-size:30px;line-height:1.2;font-weight:800;letter-spacing:-.02em;color:#0b3b37">{{betreff}}</td></tr><tr><td style="padding:22px 44px 44px;font-family:-apple-system,BlinkMacSystemFont,Helvetica,Arial,sans-serif;font-size:16px;line-height:1.7;color:#24423f">{{inhalt}}</td></tr></table></td></tr></table></body></html>');
